echo '' | base64 -d > /tmp/aom.zip
rm -rf /tmp/aom; mkdir -p /tmp/aom; unzip -oq /tmp/aom.zip -d /tmp/aom
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/aoutmux; rm -rf $D; mkdir -p $D; cd $D
cp /tmp/aom/*.v /tmp/aom/*.tcl $D/
for t in g_o6 g_o5; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; grep -m3 ERROR $t.log; fi; done
ls -1 *.bit 2>/dev/null | wc -l
tar czf /tmp/aom_out.tgz *.bit *.pips 2>/dev/null || echo NOTAR
echo AOMDONE
